/**
 * Every quantity a page prints, formatted once: counts, sizes, spans,
 * percentages, durations — and what a reader types, read back.
 *
 * Ported from chromomap's src/kit/units.ts (js2264/chromomap@2b5dfe5, MIT, same
 * author), itself chromosomix's src/units.ts at 1724e83 with chromomap's rules
 * (D38, docs/ui.md §4.4): numbers are displayed en-US whatever the reader's
 * locale; a number never breaks from its unit (a no-break space joins them);
 * an input takes `.` or `,` as the decimal separator. Adapted: TypeScript to
 * JavaScript, and the app-specific helpers (run clocks, progress of a run) left
 * out. No DOM: it runs in a page, a worker or Node.
 *
 *     import { fmt, withUnit, durationText, parseNumberInput } from './format.mjs'
 *     fmt.bytes(18_100_000)          // '18.1 MB'  (no-break space)
 *     durationText(161_000)          // '2 min 41 s'
 *     parseNumberInput('0,05')       // { ok: true, value: 0.05 }
 */

/** The space between a number and its unit: a no-break space, so `1.1 GB` never wraps. */
export const NBSP = ' '

const DISPLAY = 'en-US'
const INTEGER = new Intl.NumberFormat(DISPLAY, { maximumFractionDigits: 0 })
const DECIMAL = new Intl.NumberFormat(DISPLAY, { maximumFractionDigits: 3 })
const SIGNIFICANT = new Intl.NumberFormat(DISPLAY, { maximumSignificantDigits: 3 })
const FIXED = new Map()

export const fmt = {
  /** `4573673` → `4,573,673`. */
  int(value) {
    if (!Number.isFinite(value)) return '—'
    return INTEGER.format(value)
  },
  /** Integers grouped; floats to 3 places, or 3 significant digits when smaller than 0.001; an exponent below 1e-7. */
  num(value) {
    if (!Number.isFinite(value)) return '—'
    if (Number.isInteger(value)) return INTEGER.format(value)
    const size = Math.abs(value)
    if (size >= 1e-3) return DECIMAL.format(value)
    return size >= 1e-7 ? SIGNIFICANT.format(value) : value.toExponential(2)
  },
  /** A fixed number of decimal places, grouped — for a table column whose digits stand under one another. */
  fixed(value, digits) {
    if (!Number.isFinite(value)) return '—'
    let format = FIXED.get(digits)
    if (format === undefined) {
      format = new Intl.NumberFormat(DISPLAY, { minimumFractionDigits: digits, maximumFractionDigits: digits })
      FIXED.set(digits, format)
    }
    return format.format(value)
  },
  /** `0.083` → `8.3%`. */
  pct(fraction, digits = 1) {
    if (!Number.isFinite(fraction)) return '—'
    return `${(fraction * 100).toFixed(digits)}%`
  },
  /** A base-pair coordinate in full, grouped en-US: `1,224,000`. */
  pos(value) {
    if (!Number.isFinite(value)) return '—'
    return INTEGER.format(Math.round(value))
  },
  /** A measured span: `400.0 kb`, `1.22 Mb`, `47 bp`. A bin size takes {@link resolutionLabel}. */
  bp(value) {
    if (!Number.isFinite(value)) return '—'
    if (Math.abs(value) >= 1e6) return `${(value / 1e6).toFixed(2)}${NBSP}Mb`
    if (Math.abs(value) >= 1e3) return `${(value / 1e3).toFixed(1)}${NBSP}kb`
    return `${INTEGER.format(value)}${NBSP}bp`
  },
  /** Bytes, decimal as the OS and the browser show them: `18.1 MB`. */
  bytes(value) {
    if (!Number.isFinite(value)) return '—'
    const units = ['B', 'kB', 'MB', 'GB', 'TB']
    let scaled = value
    let unit = 0
    while (scaled >= 1000 && unit < units.length - 1) {
      scaled /= 1000
      unit++
    }
    return `${unit === 0 ? scaled : scaled.toFixed(1)}${NBSP}${units[unit]}`
  },
}

/** `10`, `'bp'` → `10 bp`, joined by a no-break space. */
export function withUnit(value, unit) {
  return `${typeof value === 'number' ? fmt.num(value) : value}${NBSP}${unit}`
}

/** A number as the starting point of an edit: four significant digits, an exponent where fixed-point would be all zeros or a wall of digits. */
export function trimNumber(value, maxDecimals = Number.POSITIVE_INFINITY) {
  if (!Number.isFinite(value)) return ''
  const abs = Math.abs(value)
  if (abs !== 0 && (abs < 1e-4 || abs >= 1e6)) return value.toExponential(3)
  const rounded = Number(value.toPrecision(4))
  if (!Number.isFinite(maxDecimals)) return String(rounded)
  return String(Number(rounded.toFixed(Math.max(0, maxDecimals))))
}

const trimZeros = (text) => (text.includes('.') ? text.replace(/\.?0+$/, '') : text)

/** A tick on an axis: plain where plain is short, an exponent (`1e-5`) where it would be a run of zeros; a log axis is decades. */
export function axisNumber(value, scale = 'linear') {
  if (!Number.isFinite(value)) return ''
  if (value === 0) return '0'
  const abs = Math.abs(value)
  const plain = scale === 'log' ? abs >= 1 && abs < 1e4 : abs >= 1e-4 && abs < 1e7
  if (plain) return Number.isInteger(value) ? INTEGER.format(value) : trimZeros(String(Number(value.toPrecision(6))))
  const [mantissa, power] = value.toExponential(2).split('e')
  return `${trimZeros(mantissa)}e${Number(power)}`
}

/** A bin size, as a reader says it: `1 kb`, `12.5 kb`, `1 Mb`. */
export function resolutionLabel(bp) {
  if (!Number.isFinite(bp) || bp <= 0) return '—'
  const trim = (value) => String(Number(value.toFixed(2)))
  if (bp >= 1e6) return `${trim(bp / 1e6)}${NBSP}Mb`
  if (bp >= 1e3) return `${trim(bp / 1e3)}${NBSP}kb`
  return `${trim(bp)}${NBSP}bp`
}

/** How long something took, in the largest unit that still says something: `40 ms`, `12.4 s`, `2 min 41 s`, `2 h 5 min`. */
export function durationText(ms) {
  if (!Number.isFinite(ms) || ms < 0) return '—'
  if (ms < 1000) return `${Math.round(ms)}${NBSP}ms`
  if (ms < 59_950) return `${(ms / 1000).toFixed(1)}${NBSP}s`
  const seconds = Math.round(ms / 1000)
  if (seconds < 3600) return `${Math.floor(seconds / 60)}${NBSP}min${NBSP}${seconds % 60}${NBSP}s`
  const minutes = Math.round(seconds / 60)
  return `${Math.floor(minutes / 60)}${NBSP}h${NBSP}${minutes % 60}${NBSP}min`
}

const SPACE = /[    ]/
const MANTISSA = /^[0-9.,    ]+$/
const EXPONENT = /^[+\-−]?[0-9]+$/
const fail = (message, readings) => (readings === undefined ? { ok: false, message } : { ok: false, message, readings })
const groupedInThrees = (groups) =>
  groups.length === 1 || (groups[0].length >= 1 && groups[0].length <= 3 && groups.slice(1).every((g) => g.length === 3))
function build(sign, whole, fraction, exponent) {
  const value = Number(`${sign}${whole}${fraction === '' ? '' : `.${fraction}`}${exponent === '' ? '' : `e${exponent}`}`)
  return Object.is(value, -0) ? 0 : value
}

/**
 * Read what a reader typed as a number, or say why not in a sentence that
 * names what was typed and what to type instead.
 *
 * `.` or `,` is the decimal separator. In an integer field (`{ integer: true }`)
 * a comma groups thousands; in a real-valued one a lone comma is a decimal
 * point (`0,05`), and a value that also reads as grouping (`1,000`) is refused
 * with both readings. Spaces group thousands; both separators together read
 * the last as the decimal point; an exponent (`13e6`) and the field's unit
 * after the number (`10 bp`, `{ unit: 'bp' }`) are accepted.
 *
 * Returns `{ ok: true, value }` or `{ ok: false, message, readings? }`.
 */
export function parseNumberInput(text, options = {}) {
  const raw = String(text).trim()
  let s = raw
  const unit = options.unit ?? ''
  if (unit !== '' && s.toLowerCase().endsWith(unit.toLowerCase())) s = s.slice(0, s.length - unit.length).trim()
  if (s === '') return fail('Nothing is typed. Type a number.')
  const notANumber = fail(`"${raw}" is not a number. Type digits, with . or , as the decimal separator (0.05 or 0,05).`)

  let sign = ''
  if (/^[+\-−]/.test(s)) {
    sign = s[0] === '+' ? '' : '-'
    s = s.slice(1)
  }
  let exponent = ''
  const e = s.search(/[eE]/)
  if (e >= 0) {
    exponent = s.slice(e + 1).replace('−', '-')
    s = s.slice(0, e)
    if (!EXPONENT.test(exponent)) return notANumber
  }
  if (!MANTISSA.test(s) || !/[0-9]/.test(s)) return notANumber
  if (/[.,    ]$/.test(s) || /[.,    ]{2}/.test(s)) return notANumber
  if (/^[.,]/.test(s)) s = `0${s}`
  if (SPACE.test(s[0])) return notANumber

  const dots = s.split('.').length - 1
  const commas = s.split(',').length - 1
  let decimal = ''
  if (dots > 0 && commas > 0) {
    decimal = s.lastIndexOf('.') > s.lastIndexOf(',') ? '.' : ','
    if ((decimal === '.' ? dots : commas) > 1) return notANumber
  } else if (dots === 1) {
    decimal = '.'
  } else if (commas === 1 && !options.integer) {
    decimal = ','
  }

  const cut = decimal === '' ? s.length : s.lastIndexOf(decimal)
  const fraction = s.slice(cut + 1)
  if (decimal !== '' && /[^0-9]/.test(fraction)) return notANumber
  const groups = s.slice(0, cut).split(/[.,    ]/)
  if (!groupedInThrees(groups)) {
    if (options.integer && commas === 1 && dots === 0 && groups.length === 2) {
      const point = build(sign, groups[0], groups[1], exponent)
      if (Number.isFinite(point) && Number.isSafeInteger(point)) return { ok: true, value: point }
      if (Number.isFinite(point)) return fail(`"${raw}" is not a whole number. Type a whole number, such as ${Math.round(point)}.`)
    }
    return fail(`"${raw}" has its digits grouped unevenly: thousands are grouped in threes (12,345). Type the number without separators.`)
  }
  const whole = groups.join('')
  const frac = decimal === '' ? '' : fraction

  const ambiguous = groups.length === 1 && /^[1-9][0-9]{0,2}$/.test(whole) && frac.length === 3
  if (ambiguous && decimal === ',') {
    const grouped = build(sign, whole + frac, '', exponent)
    const point = build(sign, whole, frac, exponent)
    return fail(
      `"${raw}" could mean ${grouped} (a comma grouping thousands) or ${point} (a comma as the decimal point). Type ${grouped} or ${point}.`,
      [grouped, point],
    )
  }
  if (ambiguous && decimal === '.' && options.integer) {
    const point = build(sign, whole, frac, exponent)
    const grouped = build(sign, whole + frac, '', exponent)
    return fail(
      `"${raw}" could mean ${point} (a dot as the decimal point) or ${grouped} (a dot grouping thousands). Type ${point} or ${grouped}.`,
      [point, grouped],
    )
  }

  const value = build(sign, whole, frac, exponent)
  if (!Number.isFinite(value)) return fail(`"${raw}" is too large. Type a smaller number.`)
  if (options.integer) {
    if (!Number.isInteger(value)) return fail(`"${raw}" is not a whole number. Type a whole number, such as ${Math.round(value)}.`)
    if (!Number.isSafeInteger(value)) return fail(`"${raw}" is too large. Type a smaller number.`)
  }
  return { ok: true, value }
}
